<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('admin',['hr_manager']);csrf_check();$id=(int)($_GET['id']??0);$a=$_POST['_action']??'';
if($a==='reply'){db()->prepare("INSERT INTO feedback_replies(ticket_id,sender,message) VALUES(?,'admin',?)")->execute([(int)$_POST['id'],trim($_POST['msg'])]);audit($u['id'],'Replied to ticket #'.(int)$_POST['id']);redirect('feedback.php?id='.(int)$_POST['id']);}
if($a==='status'&&in_array($_POST['st'],['Open','In Review','Resolved','Closed'])){db()->prepare("UPDATE feedback_tickets SET status=? WHERE id=?")->execute([$_POST['st'],(int)$_POST['id']]);audit($u['id'],'Ticket #'.(int)$_POST['id'].' → '.$_POST['st']);redirect('feedback.php?id='.(int)$_POST['id']);}
$Q="SELECT t.id,t.topic,t.subject,t.message,t.status,t.is_anonymous,t.created_at,CASE WHEN t.is_anonymous=1 THEN 'Anonymous Employee' ELSE e.full_name END who FROM feedback_tickets t LEFT JOIN employees e ON e.id=t.employee_id";
page_head('Feedback',[],$u);
if($id){$t=db()->prepare("$Q WHERE t.id=?");$t->execute([$id]);$t=$t->fetch();if(!$t)die('Not found');$r=db()->prepare("SELECT * FROM feedback_replies WHERE ticket_id=? ORDER BY id");$r->execute([$id]);?>
<a href="feedback.php">← Back</a><div class="card p-3 my-3"><div class="d-flex justify-content-between"><b><?=e($t['subject'])?></b><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="_action" value="status"><input type="hidden" name="id" value="<?=$id?>"><select class="form-select form-select-sm" name="st"><?php foreach(['Open','In Review','Resolved','Closed'] as $s)echo'<option'.($s===$t['status']?' selected':'').'>'.$s.'</option>';?></select><button class="btn btn-sm btn-outline-secondary">Update</button></form></div>
<div class="text-muted small"><?=e($t['who'])?> · <?=e($t['topic'])?> · <?=e($t['created_at'])?></div><p class="mt-2"><?=nl2br(e($t['message']))?></p></div>
<?php foreach($r as $x){?><div class="card p-2 mb-2"><small class="text-muted"><?=$x['sender']==='admin'?'Admin':e($t['who'])?> · <?=e($x['created_at'])?></small><?=nl2br(e($x['message']))?></div><?php }?>
<form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="_action" value="reply"><input type="hidden" name="id" value="<?=$id?>"><input class="form-control" name="msg" placeholder="<?=$t['is_anonymous']?'Resolution note (sender stays anonymous)':'Reply to employee'?>" required><button class="btn btn-primary">Send</button></form>
<?php }else{$f=$_GET['status']??'';$q=$f?db()->prepare("$Q WHERE t.status=? ORDER BY t.id DESC"):db()->prepare("$Q ORDER BY t.id DESC");$q->execute($f?[$f]:[]);?>
<div class="mb-3"><?php foreach(['','Open','In Review','Resolved','Closed'] as $s)echo'<a class="btn btn-sm btn-outline-secondary me-1" href="?status='.urlencode($s).'">'.($s?:'All').'</a>';?></div>
<div class="card table-responsive"><table class="table mb-0"><tr><th>Subject</th><th>From</th><th>Topic</th><th>Status</th><th>Date</th></tr><?php foreach($q as $t){?><tr><td><a href="?id=<?=$t['id']?>"><?=e($t['subject'])?></a></td><td><?=e($t['who'])?></td><td><?=e($t['topic'])?></td><td><span class="badge text-bg-<?=badge($t['status'])?>"><?=e($t['status'])?></span></td><td><?=e($t['created_at'])?></td></tr><?php }?></table></div><?php }page_foot();
